const items = $input.all();

return items.map(item => {
  // Get shift data from normalize node
  const shiftData = $('Set - Normalize Shift Report Data').first().json;

  try {
    const raw = item.json.output ?? '';
    const cleaned = raw.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(cleaned);

    // Validate primary category
    const validCategories = ['Critical Alert', 'Inventory Needs', 'Routine Log'];
    const category = validCategories.includes(parsed.primary_category)
      ? parsed.primary_category
      : 'Routine Log';

    return {
      json: {
        // AI results
        primary_category: category,
        confidence: parsed.confidence ?? 'Medium',
        ai_summary: parsed.ai_summary ?? 'Summary not available',
        critical_issues: parsed.critical_issues ?? [],
        inventory_items: parsed.inventory_items ?? [],
        technical_assessment: parsed.technical_assessment ?? '',
        recommended_action: parsed.recommended_action ?? '',
        parse_error: false,

        // Shift metadata carried forward
        batch_id: shiftData.batch_id,
        product_type: shiftData.product_type,
        distiller_name: shiftData.distiller_name,
        shift_date: shiftData.shift_date,
        ambient_temp: shiftData.ambient_temp,
        batch_ph: shiftData.batch_ph,
        specific_gravity: shiftData.specific_gravity,
        shift_notes: shiftData.shift_notes,
        received_at: shiftData.received_at
      }
    };

  } catch(error) {
    // Parse failed — default to Routine Log and flag error
    return {
      json: {
        primary_category: 'Routine Log',
        confidence: 'Low',
        ai_summary: 'AI output could not be parsed. Manual review required.',
        critical_issues: [],
        inventory_items: [],
        technical_assessment: 'Unable to assess — parse error',
        recommended_action: 'Manual review of shift report required',
        parse_error: true,

        batch_id: shiftData.batch_id,
        product_type: shiftData.product_type,
        distiller_name: shiftData.distiller_name,
        shift_date: shiftData.shift_date,
        ambient_temp: shiftData.ambient_temp,
        batch_ph: shiftData.batch_ph,
        specific_gravity: shiftData.specific_gravity,
        shift_notes: shiftData.shift_notes,
        received_at: shiftData.received_at
      }
    };
  }
});

